-- Check distinct values of vendchecklvl
SELECT DISTINCT vendchecklvl 
FROM vendors;

-- Count results from our query
SELECT COUNT(*) FROM (
    SELECT v.vendregistry
    FROM vendors v
    WHERE v.vendregistry IN (
        SELECT DISTINCT b.vendref 
        FROM transactions t 
        JOIN buyers b ON t.buyref = b.buyregistry
    )
) sub;
